package com.bookstore.controller; import com.bookstore.entity.Category; import com.bookstore.service.CategoryService;  import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; @Controller @RequestMapping("/categorys") public class CategoryController{private final CategoryService service;public CategoryController(CategoryService s){service=s;}@GetMapping String list(Model m){m.addAttribute("items",service.findAll());return "categorys/list";}@GetMapping("/new")String create(Model m){m.addAttribute("item",new Category());return "categorys/form";}@GetMapping("/edit/{id}")String edit(@PathVariable Long id,Model m){m.addAttribute("item",service.findById(id));return "categorys/form";}@PostMapping("/save")String save(@Valid @ModelAttribute("item") Category item,BindingResult r){if(r.hasErrors())return "categorys/form";service.save(item);return "redirect:/categorys";}@GetMapping("/delete/{id}")String delete(@PathVariable Long id){service.delete(id);return "redirect:/categorys";}}